import { API_BASE_URL } from '../config/api';

export interface PrivacySettings {
  dataSharing: boolean;
  location: boolean;
  analytics: boolean;
}

export async function saveSettings(settings: PrivacySettings): Promise<PrivacySettings> {
  const response = await fetch(`${API_BASE_URL}/me/privacy`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(settings),
  });
  if (!response.ok) throw new Error(`Save failed with status ${response.status}`);
  return (await response.json()) as PrivacySettings;
}

export async function exportData(): Promise<{ url: string }> {
  const response = await fetch(`${API_BASE_URL}/me/data/export`, { method: 'POST' });
  if (!response.ok) throw new Error(`Export failed with status ${response.status}`);
  return (await response.json()) as { url: string };
}

export async function deleteAccount(): Promise<{ deleted: true }> {
  const response = await fetch(`${API_BASE_URL}/me`, { method: 'DELETE' });
  if (!response.ok) throw new Error(`Delete failed with status ${response.status}`);
  return { deleted: true };
}

import { useCallback, useState } from 'react';
import { View, Text, TouchableOpacity, Switch, StyleSheet, SafeAreaView, ActivityIndicator } from 'react-native';
import { saveSettings, exportData, deleteAccount, type PrivacySettings } from '../services/privacy';

const colors = {
  accent: '#f05039',
  borderAlt: '#2a2f2a',
  text: '#f5f5f0',
  bg: '#0f120e',
  border: '#242a24',
  muted: '#8a8f8a',
  surface: '#1a1f1a',
  dangerDark: '#b91c1c',
  dangerSoft: '#fca5a5',
  warn: '#eab308',
  success: '#4ade80',
  danger: '#ff6b5e',
}

const SETTING_LABELS: Array<{ key: keyof PrivacySettings; title: string; detail: string }> = [
  { key: 'dataSharing', title: 'Data sharing', detail: 'Share usage data to improve the product' },
  { key: 'location', title: 'Location', detail: 'Allow location access for nearby features' },
  { key: 'analytics', title: 'Analytics', detail: 'Send anonymized analytics' },
];

export function PrivacyScreen(): JSX.Element {
  const [settings, setSettings] = useState<PrivacySettings>({ dataSharing: true, location: false, analytics: true });
  const [exporting, setExporting] = useState(false);
  const [exportUrl, setExportUrl] = useState<string | null>(null);
  const [confirmingDelete, setConfirmingDelete] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [deleted, setDeleted] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const toggle = useCallback((key: keyof PrivacySettings) => {
    setSettings(prev => ({ ...prev, [key]: !prev[key] }));
  }, []);

  const onExport = useCallback(async () => {
    setExporting(true);
    setError(null);
    try {
      const { url } = await exportData();
      setExportUrl(url);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Export failed.');
    } finally {
      setExporting(false);
    }
  }, []);

  const onDelete = useCallback(async () => {
    setDeleting(true);
    setError(null);
    try {
      await deleteAccount();
      setDeleted(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Delete failed.');
    } finally {
      setDeleting(false);
    }
  }, []);

  if (deleted) {
    return (
      <SafeAreaView style={styles.safe}>
        <View style={styles.centerContent}>
          <Text style={styles.deleted}>Account deleted.</Text>
        </View>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.safe}>
      <View style={styles.content}>
        <Text style={styles.title}>Privacy</Text>
        {SETTING_LABELS.map(item => (
          <View key={item.key} style={styles.row}>
            <View style={styles.rowInfo}>
              <Text style={styles.rowTitle}>{item.title}</Text>
              <Text style={styles.rowDetail}>{item.detail}</Text>
            </View>
            <Switch
              value={settings[item.key]}
              onValueChange={() => toggle(item.key)}
              trackColor={{ true: colors.accent, false: colors.borderAlt }}
              accessibilityLabel={item.title}
            />
          </View>
        ))}
        <TouchableOpacity style={styles.action} onPress={onExport} disabled={exporting} accessibilityRole="button">
          {exporting ? <ActivityIndicator color="{colors.text}" /> : <Text style={styles.actionText}>Export my data</Text>}
        </TouchableOpacity>
        {exportUrl && <Text style={styles.success}>Export ready — {exportUrl}</Text>}
        {!confirmingDelete ? (
          <TouchableOpacity style={styles.dangerGhost} onPress={() => setConfirmingDelete(true)} accessibilityRole="button">
            <Text style={styles.dangerText}>Delete account</Text>
          </TouchableOpacity>
        ) : (
          <View style={styles.confirmRow}>
            <Text style={styles.confirmText}>This cannot be undone.</Text>
            <TouchableOpacity style={styles.danger} onPress={onDelete} disabled={deleting} accessibilityRole="button">
              {deleting ? <ActivityIndicator color="{colors.text}" /> : <Text style={styles.dangerText}>Confirm delete</Text>}
            </TouchableOpacity>
          </View>
        )}
        {error && <Text style={styles.error}>{error}</Text>}
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  centerContent: { flex: 1, alignItems: 'center', justifyContent: 'center' },
  content: { padding: 20 },
  title: { fontSize: 22, fontWeight: '700', color: colors.text, marginBottom: 16 },
  row: { flexDirection: 'row', alignItems: 'center', paddingVertical: 14, borderBottomWidth: 1, borderBottomColor: colors.border },
  rowInfo: { flex: 1, paddingRight: 12 },
  rowTitle: { color: colors.text, fontWeight: '600' },
  rowDetail: { color: colors.muted, fontSize: 12, marginTop: 2 },
  action: { marginTop: 20, backgroundColor: colors.surface, borderRadius: 6, paddingVertical: 14, alignItems: 'center' },
  actionText: { color: colors.text, fontWeight: '600' },
  dangerGhost: { marginTop: 12, alignItems: 'center', paddingVertical: 10 },
  danger: { backgroundColor: colors.dangerDark, borderRadius: 6, paddingVertical: 12, paddingHorizontal: 16 },
  dangerText: { color: colors.dangerSoft, fontWeight: '600' },
  confirmRow: { marginTop: 12, gap: 8 },
  confirmText: { color: colors.warn, fontSize: 12 },
  success: { color: colors.success, marginTop: 10, fontSize: 12 },
  deleted: { color: colors.text, fontSize: 18 },
  error: { color: colors.danger, marginTop: 10 },
});
